import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load brushed metal texture
  const texture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearMipmapLinearFilter;
  texture.wrapS = THREE.ClampToEdgeWrapping;
  texture.wrapT = THREE.ClampToEdgeWrapping;

  // Create plane geometry (512x320 atlas region = 1.6:1 aspect)
  const width = 1.6;
  const height = 1;
  const planeGeometry = new THREE.PlaneGeometry(width, height);

  // Create material with brushed metal texture
  const material = new MeshBasicNodeMaterial({
    map: texture,
  });

  // Create and add plane mesh
  const planeMesh = new THREE.Mesh(planeGeometry, material);
  group.add(planeMesh);

  // Create and add text label
  let textMesh = null;
  if (ctx.fontAtlas) {
    textMesh = ctx.fontAtlas.create({
      text: config.textContent || 'Collection 2',
      font: 'Lora',
      size: 0.34,
      weight: 400,
      color: '#e8ecf2',
      align: 'center',
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Apply scene placement
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Setup resource cleanup
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    material.dispose();
    texture.dispose();
    if (textMesh && textMesh.geometry) {
      textMesh.geometry.dispose();
    }
    if (textMesh && textMesh.material) {
      textMesh.material.dispose();
    }
  };

  return group;
}
